   "n": "Состав элементов ЦИМ АР",
   "what": "Проверяет по всем файлам ЦИМ АР объекта вместе, что в них представлены требуемые группы элементов п. 5.3.2 по классам таблицы 5.3: помещения и зоны, стены, перекрытия, окна, двери, кровля — обязательно; для фасада достаточно одного из трёх классов. Колонны, лестницы, места стоянки, отделка и вывески — условные: их отсутствие не ошибка.",
   "d": "В совокупности файлов ЦИМ АР представлены все обязательные группы элементов, а для групп с альтернативным представлением — хотя бы один вариант.",
