   "6.1": {
    "caption": "Таблица 6.1 – Описание полей наименования проекций сечений ЦИМ АГР",
    "rows": [
     [
      [
       "Поле",
       1
      ],
      [
       "Значение",
       1
      ],
      [
       "Описание",
       1
      ]
     ],
     [
      [
       "Поле 1",
       1
      ],
      [
       "Номер подобъекта (секции)",
       1
      ],
      [
       "Обязательное поле.\nНомер подобъекта (секции) указывается в формате «Xxx», где «X» – «П» (подобъект) или «С» (секция); «xx» – двузначное обозначение порядкового номера. При отсутствии номера указывается «00», например, П01, С00, С02, С05 и т.п.\nВ случае привязки одной проекции сечения к нескольким подобъектам (секциям) их обозначения указываются диапазоном, например, «С01-С03» – секции 1, 2 и 3.",
       1
      ]
     ],
     [
      [
       "Поле 2",
       1
      ],
      [
       "Наименование типа вида",
       1
      ],
      [
       "Обязательное поле.\nУказывается наименование типа вида в зависимости от положения проекции сечения:\n- План этажа;\n- Разрез Х-Х;\n- Сечение Х-Х.\nПримечание: Наименование вертикальных проекций сечения (разрезов и сечений) включает в себя номерное или буквенное обозначение соответствующей секущей плоскости (Х-Х).\nДля каждой вертикальной проекции сечения применяют самостоятельный порядок нумерации или буквенного обозначения.",
       1
      ]
     ],
     [
      [
       "Поле 3",
       1
      ],
      [
       "Назначение вида",
       1
      ],
      [
       "Обязательное поле.\nДля планов этажей, относящихся к основным этажам здания, указывается значение «основной».\nДля иных планов этажей указываются значения «вспомогательный» или «дополнительный».\nДля общих продольных и поперечных разрезов по зданию указывается значение «основной».\nДля иных разрезов (сечений) указываются значения «вспомогательный» или «дополнительный».",
       1
      ]
     ],
     [
      [
       "Поле 4",
       1
      ],
      [
       "Отметка",
       1
      ],
      [
       "Обязательное поле.\nУказывается отметка проекции сечения, например: 0,000; -1,700; +3,000.\nПримечание: для разрезов по всей высоте здания допускается не заполнять Поле 4.",
       1
      ]
     ]
    ]
   },
